sp_FecharCaixa	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_FecharCaixa`(\n\n    IN p_idCaixa           INT,\n\n    IN p_idUsuario         INT,\n\n    IN p_saldoFinal        DECIMAL(10,2),\n\n    IN p_saldoFinalContado DECIMAL(10,2),\n\n    IN p_obs               VARCHAR(300)\n\n)\nBEGIN\n\n    UPDATE Caixa\n\n    SET fAtivo             = 0,\n\n        usuario_close_id   = p_idUsuario,\n\n        dthClose           = CONVERT_TZ(NOW(), '+00:00', '-03:00'),\n\n        saldoFinal         = p_saldoFinal,\n\n        saldoFinalContado  = p_saldoFinalContado,\n\n        diferenca          = p_saldoFinalContado - p_saldoFinal,\n\n        obsEncerramento    = p_obs\n\n    WHERE idCaixa = p_idCaixa;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
